head.script:
// Playwright 검증에서 handler context를 확인하기 위한 호출 이력을 저장한다.
scwin.beforeSpinCalls = [];
scwin.afterInputCalls = [];

scwin.onpageload = function() {
};

// spinner handler가 전달한 GridView row context로 종목 코드를 조회한다.
scwin.getSymbol = function(info) {
    var rowIndex = info && info.rowIndex != null ? info.rowIndex : 0;
    return dlt_order.getCellData(rowIndex, "symbol");
};

// 업무 규칙 예시: row의 종목 코드와 현재 값으로 spin increment를 결정한다.
scwin.getDynamicIncrement = function(symbol, value) {
    if (symbol === "SAMSUNG") {
        return value > 10 ? 0.05 : 0.01;
    }
    if (symbol === "SKHYNIX") {
        return value > 50 ? 2 : 1;
    }
    return 1;
};

// beforeSpinHandler 예시.
// spinner up/down 계산 직전에 호출된다. 반환한 increment는 현재 spin 1회에만 적용되고,
// cancel:true를 반환하면 증감 동작을 차단한다.
scwin.beforeSpin = function(info) {
    var symbol = scwin.getSymbol(info);
    var currentValue = Number(info.currentValue || 0);
    var result;

    if (symbol === "CANCEL") {
        result = { cancel: true };
    } else {
        result = {
            increment: scwin.getDynamicIncrement(symbol, currentValue)
        };
    }

    scwin.beforeSpinCalls.push({
        colID: info.colID,
        rowIndex: info.rowIndex,
        realRowIndex: info.realRowIndex,
        direction: info.direction,
        currentValue: info.currentValue,
        increment: result.increment,
        cancel: result.cancel === true
    });

    return result;
};

// afterInputHandler 예시.
// 내부 spinner input의 사용자 입력 처리 후 호출된다. 반환한 문자열은 입력창 표시값으로 바로 적용된다.
// 예: SAMSUNG 종목에서 10을 입력하면 10.00을 반환하고, 10.04는 그대로 반환한다.
scwin.afterInput = function(info) {
    var symbol = scwin.getSymbol(info);
    var displayFormat = symbol === "SAMSUNG" ? "#,###.00" : "#,###";
    var displayValue = info.newValue != null ? info.newValue + "" : "";
    if (symbol === "SAMSUNG" && displayValue !== "" && displayValue.indexOf(".") < 0) {
        displayValue += ".00";
    }

    scwin.afterInputCalls.push({
        colID: info.colID,
        rowIndex: info.rowIndex,
        realRowIndex: info.realRowIndex,
        oldValue: info.oldValue,
        newValue: info.newValue,
        displayFormat: displayFormat,
        displayValue: displayValue
    });

    return displayValue;
};

// inputType="custom"의 typeGetter 예시.
// 반환되는 동적 spinner에도 일반 inputType="spinner" 컬럼과 동일한 handler를 전달해
// 두 경로가 하나의 업무 규칙을 공유하도록 한다.
scwin.customTypeGetter = function(info) {
    return {
        id: "dynamic_spinner_" + info.realRowIndex + "_" + info.colIndex,
        inputType: "spinner",
        options: {
            dataType: "number",
            increment: 1,
            min: 0,
            max: 1000,
            displayFormat: "#,###.00",
            applyFormat: "all",
            viewType: "icon",
            beforeSpinHandler: "scwin.beforeSpin",
            afterInputHandler: "scwin.afterInput"
        }
    };
};

// Playwright assertion에서 마지막 handler 호출 정보를 조회하기 위한 helper 함수다.
scwin.getLatestBeforeSpinCall = function() {
    return scwin.beforeSpinCalls[scwin.beforeSpinCalls.length - 1] || null;
};

scwin.getLatestAfterInputCall = function() {
    return scwin.afterInputCalls[scwin.afterInputCalls.length - 1] || null;
};
